CREATE TABLE knowledge_job_budgets(library_id TEXT NOT NULL,job_id TEXT NOT NULL,call_limit INTEGER NOT NULL CHECK(call_limit BETWEEN 1 AND 4096),PRIMARY KEY(library_id,job_id)); CREATE TABLE knowledge_job_calls(library_id TEXT NOT NULL,job_id TEXT NOT NULL,call_id TEXT NOT NULL,lease_token TEXT NOT NULL,completed INTEGER NOT NULL CHECK(completed IN (0,1)),input_tokens INTEGER CHECK(input_tokens>=0),output_tokens INTEGER CHECK(output_tokens>=0),PRIMARY KEY(library_id,job_id,call_id),CHECK((input_tokens IS NULL)=(output_tokens IS NULL)));
